def test_negative_price_cannot_create_cash():
    from tests.test_ledger import MON, D, ledger
    from twlab.ledger import Rejection
    lg = ledger()
    try:
        f = lg.buy(security_id='A', price=D(-100), shares=1000, at=MON, event_id='b')
    except ValueError:
        return
    assert isinstance(f, Rejection), (f, lg.cash)
